 p=ART/f'state-audit-b{b}.json'; d=json.loads(p.read_text()); pre=next(x for x in d['steps'] if x['phase']=='post_prefill'); dec=[x for x in d['steps'] if x['phase']=='decode']; m=pre['mamba_indices']; r=pre['req_pool_indices']; kv=pre['kv_token_indices'];
 out['cells'].append({'batch':b,'raw_sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'model_runner':d.get('model_runner_class'),'request_slots':r,'mamba_slots':m,'req_slots_unique':len(set(r))==b,'mamba_slots_unique':len(set(m))==b,'request_equals_mamba_index':r==m,'prefill_seq_lens':pre['seq_lens'],'kv_token_ranges':[[x[0],x[-1],len(x)] for x in kv],'kv_ids_unique_across_requests':len(set(sum(kv,[])))==sum(map(len,kv)),'mamba_state_storage':{'conv_ptrs':pre['conv_ptrs'],'conv_shapes':pre['conv_shape'],'temporal_ptr':pre['temporal_ptr'],'temporal_shape':pre['temporal_shape']},'kv_storage_ptrs':{'k_layer0':pre['kv_k_ptr'],'v_layer0':pre['kv_v_ptr']},'configured_graph_batch_sizes':pre['graph_batch_sizes'],'captured_graph_keys':pre['graph_keys'],'decode_steps':len(dec),'decode_index_invariant':all(x['before']['req_pool_indices']==x['after']['req_pool_indices'] and x['before']['mamba_indices']==x['after']['mamba_indices'] for x in dec),'decode_seq_len_increments':all(all(y==x+1 for x,y in zip(z['before']['seq_lens'],z['after']['seq_lens'])) for z in dec),'decode_new_kv_per_request_unique':all(len({z['after']['kv_token_indices'][i][-1] for i in range(b)})==b for z in dec),'state_changes_observed':len(dec)>=2 and any(dec[i]['private_slot_state_abs_sums']!=dec[i+1]['private_slot_state_abs_sums'] for i in range(len(dec)-1)),'decode_mamba_state_summaries_per_request':[[row for row in z['private_slot_state_abs_sums']] for z in dec]})
